from collections import deque

def transform2(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x,grid[y][x]))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    motif=max(comps,key=len)
    mr0=min(r for r,c,v in motif); mr1=max(r for r,c,v in motif)
    mc0=min(c for r,c,v in motif); mc1=max(c for r,c,v in motif)
    ar=(mr0+mr1)//2; ac=(mc0+mc1)//2
    anchors=[comp[0][:2] for comp in comps if comp is not motif]
    out=[row[:] for row in grid]
    for rr,cc in anchors:
        for r,c,v in motif:
            y=rr+r-ar; x=cc+c-ac
            if 0<=y<h and 0<=x<w: out[y][x]=v
    return out

